def calculate_marble_price():
    original_price = 20
    price_increase = 0.20
    months = 36
    months_per_increase = 2

    current_price = original_price
    for _ in range(months // months_per_increase):
        current_price *= (1 + price_increase)

    return round(current_price, 2)

print(calculate_marble_price())

def calculate_guests():
    # Define the costs for each venue
    flat_fee = 200
    food_cost_per_guest = 5
    cost_per_guest_at_second_venue = 25

    # Calculate the cost for the first venue
    def cost_first_venue(guests):
        return flat_fee + food_cost_per_guest * guests

    # Calculate the cost for the second venue
    def cost_second_venue(guests):
        return cost_per_guest_at_second_venue * guests

    # Find the number of guests where the costs are equal
    guests = 0
    while True:
        if cost_first_venue(guests) == cost_second_venue(guests):
            break
        elif cost_first_venue(guests) > cost_second_venue(guests):
            guests += 1
        else:
            guests -= 1

    return guests

# Print the final answer
print(calculate_guests())
